def finish():
    entries=[]
    for old in BASE['entries']:
        if old['id'] not in PATCH:continue
        e=PATCH[old['id']]
        before=set(re.findall(r'\[@(src-[^\]]+)\]',json.dumps(old['fields'],ensure_ascii=False)))
        after=set(re.findall(r'\[@(src-[^\]]+)\]',json.dumps(e['fields'],ensure_ascii=False)))
        if before!=after:raise ValueError(('Changed source set',old['id'],before-after,after-before))
        if not 60<=len(e['summary'])<=140:raise ValueError(('summary length',e['id'],len(e['summary'])))
        clean=lambda text:re.sub(r'\[@[^\]]+\]','',text)
        e['fields']['evidence']=e['fields']['evidence'].replace('C，机构临床与患者指导；不以症状自诊或替个体开处方。','C，机构的症状评估与处理指导。')
        e['audit'].pop('evidence_and_source_fields_preserved',None)
        e['audit'].update(evidence_grade_and_scope_preserved=True,evidence_text_unchanged=e['fields']['evidence']==old['fields']['evidence'],source_field_unchanged=e['fields']['sources']==old['fields']['sources'])
        e['audit'].update(original_plain_chars=len(old['fields']['plain']),new_plain_chars=len(e['fields']['plain']),source_tokens_preserved=True,original_numbers=re.findall(r'\d+(?:[.–—-]\d+)?',clean(old['fields']['plain'])),new_numbers=re.findall(r'\d+(?:[.–—-]\d+)?',clean(e['fields']['plain'])),clinical_numbers_review='按原文保留影响行动的剂量、时限、比较人群及禁忌；重复数字可合并，书写数字不同不自行推定临床等效。')
        entries.append(e)
    (HERE/'intimate-rewrites.json').write_text(json.dumps(entries,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    report=dict(checked_at='2026-10-30',scope='乳房腋下/腹部肚脐/私密生育/肛周/体毛/瘢痕100条逐条表达审查',reviewed=len(entries),expected=len(BASE['entries']),complete=len(entries)==len(BASE['entries']),clinical_review_status='not_clinically_reviewed',original_plain_chars=sum(len(ORIGINAL[e['id']]['fields']['plain']) for e in entries),new_plain_chars=sum(len(e['fields']['plain']) for e in entries),ids=[e['id'] for e in entries],entry_reviews=[dict(id=e['id'],**e['audit']) for e in entries],source_ledger_read=dict(matched_records=164,read_fields=['support','limitations'],full_medical_research_repeated=False),blocking_unresolved=[],merge_targets=[m['target'] for m in MERGES],merge_rejected=[dict(target='bodyskin-013',retired='bodyskin-014',reason='年龄标签不同，不能用较广target给儿童暴露成人专属建议。')])
    (HERE/'intimate-audit.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    for m in MERGES:
        if not 60<=len(m['summary'])<=140:raise ValueError(('merge summary',m['target'],len(m['summary'])))
        before=set(re.findall(r'\[@(src-[^\]]+)\]','\n'.join(json.dumps(ORIGINAL[i]['fields'],ensure_ascii=False) for i in [m['target'],*m['retired']])))
        after=set(re.findall(r'\[@(src-[^\]]+)\]',json.dumps(m['fields'],ensure_ascii=False)))
        if before!=after:raise ValueError(('merge citations',m['target']))
    (HERE/'intimate-merges.json').write_text(json.dumps(MERGES,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(report['reviewed'],report['original_plain_chars'],report['new_plain_chars'])
if __name__=='__main__':finish()
